def _check_gamma(cls, gamma, epsilon=None):
    if gamma is None and epsilon is not None:
        gamma = 1 / (1 + np.exp(epsilon / 2))

    if not isinstance(gamma, Real):
        raise TypeError("Gamma must be numeric")
    if not 0.0 <= gamma <= 1.0:
        raise ValueError("Gamma must be in [0,1]")

    return float(gamma)

def randomise(self, value):
    self._check_all(value)

    noisy_value = super().randomise(value)
    return self._fold(noisy_value)

def _check_bounds(cls, lower, upper):
    """Performs a check on the bounds provided for the mechanism."""
    if not isinstance(lower, Real) or not isinstance(upper, Real):
        raise TypeError("Bounds must be numeric")

    if lower > upper:
        raise ValueError("Lower bound must not be greater than upper bound")

    return lower, upper
